const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const alabama = ee.FeatureCollection('TIGER/2018/States')
        .filter(ee.Filter.eq('NAME', 'Alabama'))
        .geometry();

    const startDate1 = '2003-01-01';
    const endDate1 = '2003-12-31';
    const startDate2 = '2012-01-01';
    const endDate2 = '2012-12-31';

    // 2. Data Acquisition & Check
    const graceCollection = ee.ImageCollection('NASA/GRACE/MASS_GRIDS/LAND')
        .select('lwe_thickness_csr');

    const collection2003 = graceCollection.filterDate(startDate1, endDate1);
    const collection2012 = graceCollection.filterDate(startDate2, endDate2);

    const size2003 = collection2003.size().getInfo();
    const size2012 = collection2012.size().getInfo();

    if (size2003 === 0 || size2012 === 0) {
        console.log(`Image count for 2003: ${size2003}`);
        console.log(`Image count for 2012: ${size2012}`);
        console.log("Empty collection for one or both periods.");
        console.log("C1");
        return;
    }

    // 3. Processing
    const meanImage2003 = collection2003.mean();
    const meanImage2012 = collection2012.mean();

    const scale = 30000; // GRACE data is coarse resolution

    const stats2003 = meanImage2003.reduceRegion({
        reducer: ee.Reducer.mean().combine({
            reducer2: ee.Reducer.count(),
            sharedInputs: true
        }),
        geometry: alabama,
        scale: scale,
        maxPixels: 1e9
    });

    const stats2012 = meanImage2012.reduceRegion({
        reducer: ee.Reducer.mean().combine({
            reducer2: ee.Reducer.count(),
            sharedInputs: true
        }),
        geometry: alabama,
        scale: scale,
        maxPixels: 1e9
    });

    const mean2003 = stats2003.get('lwe_thickness_csr_mean').getInfo();
    const count2003 = stats2003.get('lwe_thickness_csr_count').getInfo();

    const mean2012 = stats2012.get('lwe_thickness_csr_mean').getInfo();
    const count2012 = stats2012.get('lwe_thickness_csr_count').getInfo();

    // 4. Validation & Final Answer
    console.log(`2003 Image Count: ${size2003}`);
    console.log(`2012 Image Count: ${size2012}`);
    console.log(`2003 Mean Water Anomaly (cm): ${mean2003 ? mean2003.toFixed(2) : 'N/A'}, Pixels: ${count2003}`);
    console.log(`2012 Mean Water Anomaly (cm): ${mean2012 ? mean2012.toFixed(2) : 'N/A'}, Pixels: ${count2012}`);

    if (count2003 === 0 || count2012 === 0) {
        console.log("No valid pixels found in the region for one or both periods.");
        console.log("C2");
        return;
    }

    if (mean2003 === null || mean2012 === null) {
        console.log("Calculation failed, result is null.");
        console.log("C3");
        return;
    }

    if (mean2012 < mean2003) {
        console.log("Water storage decreased from 2003 to 2012.");
        console.log("A");
    } else {
        console.log("Water storage did not decrease from 2003 to 2012.");
        console.log("B");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error('Authentication or Initialization error:', e);
        console.log("D");
    }
}

initEE();
